/* ---------- batch five ---------- */
.ch{padding:0}
.ch-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 10px}
.ch-val{display:flex;align-items:center;gap:10px;margin-top:4px;font-family:var(--mono);font-weight:700;font-size:26px;letter-spacing:-.5px}
.ch-legend{display:flex;gap:16px;padding:10px 16px 14px;font-size:12px;color:var(--text-dim)}
.ch-legend span{display:inline-flex;align-items:center;gap:6px}
.sw.dash{background:repeating-linear-gradient(90deg,var(--muted) 0 3px,transparent 3px 5px);height:2px;width:12px}
.ch-tip{position:absolute;top:6px;padding:6px 8px;background:var(--panel);border:1px solid var(--icon-line);font-size:12px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none;z-index:2}
.ch-tip .mono-xs{display:block;font-size:10px}
.ch-tip b{font-family:var(--mono)}

/* line chart */
.ch-plot{position:relative;height:190px;margin:0 16px 0 44px;cursor:crosshair;touch-action:none}
.ch-plot svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.ch-plot .ln{fill:none;stroke:var(--accent);stroke-width:1.75;vector-effect:non-scaling-stroke}
.ch-plot .ln.prev{stroke:var(--muted);stroke-dasharray:3 3;stroke-width:1}
.ch-plot .gl{stroke:var(--line);stroke-width:1;vector-effect:non-scaling-stroke}
.ch-ylab{position:absolute;left:-40px;top:0;bottom:0;width:32px}
.ch-ylab span{position:absolute;right:0;transform:translateY(-50%);font-family:var(--mono);font-size:10px;color:var(--muted)}
.ch-plot.active .scrub,.ch-plot.active .scrub-dot,.ch-plot.active .ch-tip{opacity:1}

/* line chart: numbers line up with the heading, more room around the legend */
#c41 .ch-plot{margin-left:58px}
#c41 .ch-ylab{left:-42px;width:36px}
#c41 .ch-ylab span{left:0;right:auto}
#c41 .ch-legend{padding:22px 16px 18px}

/* ---------- line chart ---------- */
{
  const plot = $('#lcx-plot'), N = 30;
  function series(seed, base, drift, vol){ const r = rng(seed); const out = []; let v = base; for (let i = 0; i < N; i++){ v += (r() - .45) * vol + drift; out.push(Math.max(50, v)); } return out; }
  const ranges = {
    7:  { cur:series(11, 1180, 6, 60), prev:series(21, 1120, 3, 50), span:7 },
    30: { cur:series(12, 980, 9, 70), prev:series(22, 940, 5, 60), span:30 },
    90: { cur:series(13, 720, 14, 90), prev:series(23, 700, 8, 80), span:90 }
  };
  let shown = { cur:ranges[30].cur.slice(), prev:ranges[30].prev.slice(), lo:0, hi:1 }, key = 30, tw = 0;
  const W = 400, H = 180;
  const bounds = r => { const all = r.cur.concat(r.prev); const lo = Math.min(...all), hi = Math.max(...all); const pad = (hi - lo) * .12; return [Math.floor((lo - pad) / 50) * 50, Math.ceil((hi + pad) / 50) * 50]; };
  const toPts = (arr, lo, hi) => arr.map((v, i) => [i / (N - 1) * W, H - (v - lo) / (hi - lo) * H]);
  function draw(s){
    const c = toPts(s.cur, s.lo, s.hi), p = toPts(s.prev, s.lo, s.hi), line = smooth(c);
    $('#lcx-line').setAttribute('d', line); $('#lcx-prev').setAttribute('d', smooth(p)); $('#lcx-area').setAttribute('d', line + ` L${W},${H} L0,${H} Z`);
    const ticks = [0, .5, 1].map(t => s.lo + (s.hi - s.lo) * t);
    $('#lcx-grid').innerHTML = ticks.map(t => { const y = H - (t - s.lo) / (s.hi - s.lo) * H; return `<line class="gl" x1="0" x2="${W}" y1="${y}" y2="${y}"/>`; }).join('');
    $('#lcx-ylab').innerHTML = ticks.map(t => `<span style="top:${100 - (t - s.lo) / (s.hi - s.lo) * 100}%">${Math.round(t / 10) * 10 >= 1000 ? (t / 1000).toFixed(1) + 'k' : Math.round(t)}</span>`).join('');
  }
  function stats(r){
    countTo($('#lc-val'), Math.round(r.cur[N - 1]));
    const a = r.cur.reduce((x, y) => x + y, 0), b = r.prev.reduce((x, y) => x + y, 0), d = Math.round((a - b) / b * 100);
    setPill($('#lc-delta'), d >= 0 ? 'done' : 'fail', (d >= 0 ? '+' : '') + d + '%');
  }
  function go(k){
    key = k; const r = ranges[k], [lo, hi] = bounds(r), from = { cur:shown.cur.slice(), prev:shown.prev.slice(), lo:shown.lo, hi:shown.hi }, t0 = performance.now();
    cancelAnimationFrame(tw); stats(r);
    const step = now => {
      const t = reduce ? 1 : Math.min(1, (now - t0) / 650), e = 1 - Math.pow(1 - t, 3), L = (a, b) => a + (b - a) * e;
      shown = { cur:from.cur.map((v, i) => L(v, r.cur[i])), prev:from.prev.map((v, i) => L(v, r.prev[i])), lo:L(from.lo, lo), hi:L(from.hi, hi) };
      draw(shown); if (t < 1) tw = requestAnimationFrame(step);
    };
    tw = requestAnimationFrame(step);
  }
  { const [lo, hi] = bounds(ranges[30]); shown.lo = lo; shown.hi = hi; draw(shown); }
  segInit($('#lcx-seg'), v => go(+v));
  let last = -1;
  function scrub(e){
    const r = plot.getBoundingClientRect(), x = Math.max(0, Math.min(r.width, e.clientX - r.left)), i = Math.round(x / r.width * (N - 1));
    const px = i / (N - 1) * r.width, py = (H - (shown.cur[i] - shown.lo) / (shown.hi - shown.lo) * H) / H * r.height;
    plot.classList.add('active'); $('#lcx-scrub').style.left = px + 'px'; const dot = $('#lcx-dot'); dot.style.left = px + 'px'; dot.style.top = py + 'px';
    const span = ranges[key].span, date = addDays(TODAY, -Math.round((N - 1 - i) / (N - 1) * (span - 1)));
    const tip = $('#lcx-tip'); tip.innerHTML = `<span class="mono-xs">${fmtDay(date)}</span>This period <b>${Math.round(shown.cur[i]).toLocaleString('en-US')}</b><br>Previous <b>${Math.round(shown.prev[i]).toLocaleString('en-US')}</b>`;
    tip.style.left = Math.min(r.width - tip.offsetWidth, Math.max(0, px + 12 > r.width - tip.offsetWidth ? px - tip.offsetWidth - 12 : px + 12)) + 'px';
    if (i !== last){ last = i; Sound.play('stream'); }
  }
  plot.addEventListener('pointermove', scrub); plot.addEventListener('pointerdown', scrub);
  plot.addEventListener('pointerleave', () => { plot.classList.remove('active'); last = -1; });
  whenSeen($('#c41'), () => stats(ranges[30]));
}
